from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
DATE = "2026-09-14"
DISPLAY = "September 14, 2026"

blogs = [
    ("offshore-role-outcome-definition", "Define outcomes before opening an offshore role", "translate a staffing request into observable service outcomes", "requested outcome, service users, baseline evidence, review owner, and decision date"),
    ("philippines-offshore-onboarding-dependency-map", "Map dependencies for Philippines offshore onboarding", "surface the people, systems, and approvals that can delay a new starter", "dependency, prerequisite, accountable owner, due date, and safe fallback"),
    ("remote-work-acceptance-example-library", "Build an acceptance-example library for remote work", "show contributors what acceptable work looks like without relying on private coaching", "work type, approved example, rejection reason, reviewer, and version date"),
    ("offshore-queue-priority-evidence", "Make offshore queue priorities evidence-based", "sequence work using declared service impact and deadlines", "request time, impact class, deadline source, dependency, and priority owner"),
    ("philippines-offshore-ramp-observation-log", "Keep a Philippines offshore ramp observation log", "separate onboarding evidence from impressions about a new specialist", "task observed, instruction version, result, coaching action, and next check"),
    ("remote-coverage-handoff-rehearsal", "Rehearse a remote coverage handoff", "verify that another authorised owner can continue essential work during an absence", "queue snapshot, access check, open decisions, temporary owner, and restoration trigger"),
    ("offshore-workflow-input-quality-check", "Check input quality in an offshore workflow", "identify missing or conflicting inputs before they become rework", "required field, source system, completeness result, exception owner, and resolution time"),
    ("philippines-offshore-coaching-evidence", "Record evidence for Philippines offshore coaching", "connect feedback to observable work and a fair follow-up", "work sample, stated standard, specific gap, agreed practice, and reassessment date"),
    ("remote-service-boundary-review", "Review boundaries in a remote service lane", "keep routine preparation distinct from decisions that require client authority", "routine action, prohibited decision, escalation trigger, approver, and interim state"),
    ("offshore-tool-access-expiry-review", "Review expiry dates for offshore tool access", "remove permissions that no longer support approved work", "identity, system, permission purpose, approver, expiry date, and removal evidence"),
    ("philippines-offshore-meeting-output-record", "Turn Philippines offshore meetings into usable output records", "preserve decisions and next actions across time zones", "decision, evidence considered, action owner, due time, and unresolved question"),
    ("remote-operations-change-readiness-check", "Run a remote operations change-readiness check", "verify that a workflow change is understood, accessible, and reversible", "change scope, affected roles, training evidence, rollback owner, and review window"),
]

def q(v): return v.replace("\\", "\\\\").replace("'", "\\'")
rows = ["['%s','%s','%s','%s']" % tuple(map(q, row)) for row in blogs]
ts = f"""type Topic={{slug:string;title:string;purpose:string;record:string}};
const image='/images/thumbnail-backgrounds/operations-board.webp';
const topics:Topic[]=[{','.join(rows)}].map(([slug,title,purpose,record])=>({{slug,title,purpose,record}})) as Topic[];
const make=(t:Topic)=>({{sections:[
{{heading:'Define the operating decision',paragraphs:[`Published {DISPLAY}. Use this practice to ${{t.purpose}}. Name the decision, accountable owner, and latest useful decision time.`,`Connect the question to one real handoff or service commitment so each field has a clear purpose.`]}},
{{heading:'Create verifiable evidence',paragraphs:[`The minimum record includes ${{t.record}}. Add source links and timestamps so a reviewer can distinguish current evidence from assumptions.`,`Keep sensitive material in approved systems and record what was checked, what remains unresolved, and who can resolve it.`]}},
{{heading:'Set authority and stop conditions',paragraphs:[`List routine actions the offshore specialist may complete and decisions requiring consultation or approval. Queue ownership does not transfer authority for policy, employment, security, legal, or commercial decisions.`,`A stop condition names the trigger, recipient, evidence packet, and safe interim state so uncertainty is escalated instead of guessed.`]}},
{{heading:'Test ordinary and exception paths',paragraphs:[`Run an ordinary example, an incomplete request, conflicting instructions, and an unavailable approver through the workflow. Observe where context or ownership breaks.`,`Repair the instruction or permission where the failure appeared; do not depend on an undocumented workaround.`]}},
{{heading:'Review outcomes on a fixed cadence',paragraphs:[`Inspect queue age, returned work, missing evidence, escalation response, and accepted handoffs. These process measures do not prove individual capability or causation.`,`Compare several stable cycles and annotate demand, staffing, policy, or system changes that could explain differences.`]}},
{{heading:'Retain only useful controls',paragraphs:[`Keep the practice when it makes a decision, risk, or owner clearer. Simplify unused fields and strengthen gates that repeatedly catch consequential errors.`,`Assign an owner and review date. Offshore Resourcing can support documented coordination; the client retains final authority over people, policy, access, and material exceptions.`]}}
],faqs:[{{q:'Who owns the final decision?',a:'The named client manager or authorised specialist; the offshore operator prepares and routes evidence.'}},{{q:'How should the team begin?',a:'Pilot with a small set of routine and exception cases before expanding scope.'}}]}});
export const dailyBlogSep14Posts=topics.map((t,i)=>({{slug:t.slug,title:t.title,excerpt:`A practical guide to ${{t.purpose}}.`,minutes:8+i%3,publishedAt:'{DATE}' as const,image,details:make(t)}}));
export const dailyBlogSep14Details=Object.fromEntries(dailyBlogSep14Posts.map(p=>[p.slug,p.details]));
"""
(ROOT/'app'/'daily-blog-2026-09-14.ts').write_text(ts)

research = [
 ("offshore-intake-completeness-observation", "Observing Completeness in Offshore Work Intake", "intake completeness", "eligible requests entering one approved offshore work queue", "twenty consecutive business days"),
 ("remote-handoff-delay-measurement", "A Bounded Method for Measuring Remote Handoff Delay", "handoff delay", "completed handoffs in one defined remote service lane", "six consecutive operating weeks"),
 ("philippines-offshore-escalation-quality-study", "Designing a Philippines Offshore Escalation Quality Study", "escalation record quality", "eligible escalation records in one approved workflow", "one full calendar month"),
 ("offshore-access-review-reproducibility", "Testing Reproducibility in Offshore Access Reviews", "access-review reproducibility", "active permissions reviewed under one approved access policy", "a baseline review and repeat review thirty days later"),
 ("remote-coverage-recovery-observation", "An Observation Framework for Remote Coverage Recovery", "coverage recovery", "documented coverage events in one remote operating team", "eight consecutive operating weeks"),
]
sources = '''1. [NIST Engineering Statistics Handbook](https://www.itl.nist.gov/div898/handbook/)\n2. [GAO Standards for Internal Control](https://www.gao.gov/products/gao-14-704g)\n3. [UK Government Service Manual: Measuring Success](https://www.gov.uk/service-manual/measuring-success)\n4. [OECD Handbook on Constructing Composite Indicators](https://www.oecd.org/sdd/42495745.pdf)\n5. [NIST Risk Management Framework](https://csrc.nist.gov/projects/risk-management/about-rmf)\n6. [ILO Teleworking Guidance](https://www.ilo.org/topics/teleworking)\n7. [W3C Web Content Accessibility Guidelines](https://www.w3.org/TR/WCAG22/)\n8. [CISA Cybersecurity Performance Goals](https://www.cisa.gov/cross-sector-cybersecurity-performance-goals)\n9. [NIH Rigor and Reproducibility](https://grants.nih.gov/policy-and-compliance/policy-topics/reproducibility)\n10. [US Census Statistical Quality Standards](https://www.census.gov/about/policies/quality/standards.html)'''
images = ["workforce-dashboard.webp","capacity-planning.webp","quality-review.webp","handoff-lanes.webp","document-workflow.webp"]
for i,(slug,title,construct,population,window) in enumerate(research):
 body=f'''---\ntitle: "{title}"\ndescription: "A bounded research design for examining {construct} in distributed operations without overstating causal evidence."\ndatePublished: "{DATE}"\npublishedAt: "{DATE}"\nverifiedAt: "{DATE}"\ncategory: offshore-operating-models\nimage: "/images/thumbnail-backgrounds/{images[i]}"\nsourceCount: "10"\n---\n\n*Published: {DISPLAY}*\n\n## Research question\n\n+How can an authorised operations team examine {construct} using records already present in a controlled workflow? The purpose is a repeatable descriptive view, not a universal benchmark or service promise.\n\n## Methodology\n\n+Use a preregistered observational protocol. Define the unit, eligible states, timestamps, exclusions, missing-data codes, and review procedure before selection. Remove direct identifiers and preserve a dated data dictionary. Two trained reviewers independently classify a calibration set, reconcile the rubric, then review the bounded population. Report counts, medians, ranges, category shares, and missingness with an auditable analysis log.\n\n## Scope, population, and observation window\n\n+The population is {population}. The observation window is {window}. Exclude records outside that workflow, period, or eligibility rule. The unit is one eligible record, not an employee, client, or provider. Results describe only this operating context and require a new sampling frame before generalisation.\n\n## Measures and quality checks\n\n+Define {construct} with observable fields. Validate timestamp order, duplicate handling, timezone conversion, and statuses. Report eligible, excluded, incomplete, and reviewed counts. Recheck a fixed sample against the source system and have a second reviewer reproduce the frozen summary.\n\n## Analysis plan\n\n+Begin with the full distribution and reason categories. Compare only prespecified groups with enough records to preserve privacy and avoid unstable percentages. Annotate staffing, demand, policy, and system changes during the window.\n\n## Inference and causal boundaries\n\n+This design can identify recorded patterns and measurement gaps inside the stated population and window. It cannot establish that location, staffing model, an individual, or a management practice caused them. Task mix, demand, outages, policy changes, and unrecorded work are alternatives. Causal claims require a separate comparison design and controls for confounding.\n\n## Limitations\n\n+Records may omit informal coordination, use inconsistent timestamps, or reflect behavior changed by observation. Small samples create unstable rates. Agreement does not prove a record is true, and a clean record does not prove a good outcome. Publish exclusions and missingness, avoid individual ranking, and withdraw unsupported conclusions.\n\n## Decision use\n\n+Findings may justify clarifying one field, adjusting a handoff, scheduling review, or testing a revised control. The authorised manager names the action, owner, review date, and reversal evidence. Offshore Resourcing can prepare the documented analysis; the client retains decisions about people, policy, access, security, and service commitments.\n\n## Sources and references\n\n{sources}\n'''.replace('\n+','\n')
 (ROOT/'content'/'research'/f'{slug}.md').write_text(body)

data=ROOT/'app'/'data.ts'; s=data.read_text(); s=s.replace("import { dailyBlogSep11Posts } from './daily-blog-2026-09-11';", "import { dailyBlogSep11Posts } from './daily-blog-2026-09-11';\nimport { dailyBlogSep14Posts } from './daily-blog-2026-09-14';"); s=s.replace('...dailyBlogSep11Posts,', '...dailyBlogSep14Posts,\n  ...dailyBlogSep11Posts,'); data.write_text(s)
page=ROOT/'app'/'blog'/'[slug]'/'page.tsx'; s=page.read_text(); s=s.replace("import { dailyBlogSep11Details, dailyBlogSep11Posts } from '../../daily-blog-2026-09-11';", "import { dailyBlogSep11Details, dailyBlogSep11Posts } from '../../daily-blog-2026-09-11';\nimport { dailyBlogSep14Details, dailyBlogSep14Posts } from '../../daily-blog-2026-09-14';"); s=s.replace('...dailyBlogSep11Posts,', '...dailyBlogSep14Posts,\n    ...dailyBlogSep11Posts,'); s=s.replace('...dailyBlogSep11Details,', '...dailyBlogSep14Details,\n    ...dailyBlogSep11Details,'); page.write_text(s)
print('generated 12 blog records and 5 research documents')
